#!/usr/bin/env python3
"""test_hft_loveland.py — R80f.17–R80f.27 (HFT Loveland, v81cf21): the 11 tool tests of the Harbor Freight Loveland
take-off (tool fixes BE-HF1..BE-HF17) joined in one file so the skill stays < 200 files. No test removed: each block is the
original test_<name>.py, unchanged, run in its own namespace. All fail with the v81cf18 originals."""
import os, sys
AQ = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, AQ)

BLOQUES = []

BLOQUES.append(('test_hat_channel_label', '#!/usr/bin/env python3\n"""test_hat_channel_label.py — BE-HF1 (HFT Loveland, BE-CF15 line): a wall type that prints a vertical METAL HAT\nCHANNEL furring (e.g. \'1-1/2" metal hat channel @ 24" O.C. mounted vertically over the existing back-up surface\')\nhad no family: the reading had to write \'Z-furring slot\' in stud_size and the Material Summary said\n\'1-1/2" Z-furring channel\'. Now canon.STUD_FAM sends "hat channel" to the vertical-furring family (pieces by O.C.,\nno runner rows), canon.py writes nombres_contexto.z_kind and plantilla_excel.nombre_plantilla labels the row with the\nprinted product. Z-furring sets keep their label. Fails with v81cf18 (no z_kind, no \'hat channel\' key)."""\nimport os, sys\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nimport canon\nimport plantilla_excel as P\n\nF = "1-1/2\\" Z-furring"\n# 1. family: a stud_size that only says hat channel falls in the vertical-furring family\nk = next((f for key, f in canon.STUD_FAM if key in \'1-1/2" metal hat channel\'.lower()), None)\nassert k == F, k\n# 2. Excel label = printed product\nassert P.nombre_plantilla(F, {"nombres_contexto": {"z_size": "1-1/2\\"", "z_kind": "hat channel"}}) == \\\n    "1-1/2\\" metal hat channel, vertical furring (LF of material)"\nassert "Z-furring" not in P.nombre_plantilla(F, {"nombres_contexto": {"z_kind": "hat channel"}})\nassert P.nombre_plantilla(F, {"nombres_contexto": {"z_size": "2\\"", "z_kind": "Z-furring"}}) == "2\\" Z-furring channel (LF of material)"\nassert P.nombre_plantilla(F, {"nombres_contexto": {}}) == "1-1/2\\" Z-furring channel (LF of material)"\nassert "Z-furring / metal hat channel" in P.nombre_plantilla(F, {"nombres_contexto": {"z_kind": "Z-furring / hat channel"}})\n# 3. purchase class unchanged (hat / furring channel stock)\nsel = P.clase_compra({"material": "1-1/2\\" metal hat channel, vertical furring (LF of material)", "unit": "LF", "metal": True})\nassert sel and sel[0].startswith("hat channel"), sel\n# 4. canon.py emits z_kind\nsrc = open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "canon.py"), encoding="utf-8").read()\nassert \'"z_kind"\' in src and "z_furring_kind" in src\nprint("test_hat_channel_label OK")\nimport familias\nassert familias.familia("1-1/2\\" metal hat channel, vertical furring (LF of material)", "lf") == F, "Excel row not read back as its family (R80.4)"\nassert familias.familia("7/8\\" hat channel furring @ 16\\" O.C.", "lf") != F\nprint("test_hat_channel_label familias OK")\n'))
BLOQUES.append(('test_frp_misc_alias', '#!/usr/bin/env python3\n"""test_frp_misc_alias.py — BE-HF2 (HFT Loveland): FRP carried as a misc item with the Excel product name\n("FRP panels", G.C. finish per the finish schedule) stopped canon.py ("misc_items.familia debe ser una de FAMS").\nNow canon.MISC_ALIAS maps it to the FRP family, whose Material Summary row is "FRP panels" with the item source.\nFails with v81cf18 (no MISC_ALIAS)."""\nimport os, sys\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nimport canon\nimport plantilla_excel as P\nassert canon.MISC_ALIAS["FRP panels"] == canon.F_FRP\nassert P.nombre_plantilla(canon.F_FRP, {}) == "FRP panels"\nsrc = open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "canon.py"), encoding="utf-8").read()\nassert "it[\\"familia\\"] = MISC_ALIAS[it[\\"familia\\"]]" in src\nprint("test_frp_misc_alias OK")\n'))
BLOQUES.append(('test_furring_no_bracing', '#!/usr/bin/env python3\n"""test_furring_no_bracing.py — BE-HF3 (HFT Loveland; CFA River Point TOOL_LIMITS #8): canon.py generated C.R. channel\nbracing rows on vertical furring (Z-furring on CMU, hat channel over masonry) because every vertical run got\nROUNDUP(H x 12 / spacing) - 1 rows. Furring fastened to its back-up surface gets 0 rows (with source) unless the canon\ndeclares bracing_rows; corridas.py then writes 0 LF. Synthetic data. Fails with v81cf18 (no furring_sin_bracing)."""\nimport os, sys\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nimport canon\nimport corridas\n\ndef w(stud, **k):\n    return dict({"id": "<wall>", "stud_size": stud, "detail": "F/X4.1"}, **k)\n\na = canon.furring_sin_bracing(w(\'1-1/2" metal hat channel\'), "X1.1")\nassert a["bracing_rows"] == 0 and a["bracing_rows_source"].startswith("F/X4.1"), a\nassert canon.furring_sin_bracing(w(\'1-1/2" Z-furring\'), "X1.1")["bracing_rows"] == 0\nassert "bracing_rows" not in canon.furring_sin_bracing(w(\'6"\'), "X1.1")\nd = canon.furring_sin_bracing(w(\'1-1/2" metal hat channel\', bracing_rows=1, bracing_rows_source="F/X4.1"), "X1.1")\nassert d["bracing_rows"] == 1\nsrc = open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "canon.py"), encoding="utf-8").read()\nassert "w = furring_sin_bracing(w, src)" in src\nprint("test_furring_no_bracing OK")\n'))
BLOQUES.append(('test_vigas_min_size', '#!/usr/bin/env python3\n"""test_vigas_min_size.py — BE-HF4 (HFT Loveland): vigas_sobre_walls._grids used a fixed 14 pt minimum label size; a set\nwith 9-10 pt grid labels gave "registro: 0 grid(s) comunes". main() now takes --min-size (default 14). Synthetic page.\nFails with v81cf18 (option ignored, 0 grids)."""\nimport os, sys\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nimport pymupdf\nimport vigas_sobre_walls as V\ndoc = pymupdf.open()\npg = doc.new_page(width=1000, height=800)\nfor i, x in enumerate((100, 300, 500), 1):\n    pg.insert_text((x, 50), str(i), fontsize=9)\nfor l, y in (("A", 200), ("B", 400), ("C", 600)):\n    pg.insert_text((50, y), l, fontsize=9)\nassert len(V._grids(pg)) < 2\ng = V._grids(pg, 8.0)\nassert {"1", "2", "3", "A", "B", "C"} <= set(g), g\nsrc = open(V.__file__, encoding="utf-8").read()\nassert \'"--min-size"\' in src and \'float(opts["--min-size"])\' in src\nprint("test_vigas_min_size OK")\n'))
BLOQUES.append(('test_bracing_spacing_regla', '#!/usr/bin/env python3\n"""test_bracing_spacing_regla.py — BE-HF5 (HFT Loveland): reglas.py A_BRACING (53.4) checked every vertical run against\nROUNDUP(H x 12 / 48) - 1 even when the set prints the C.R. channel spacing (constants.bracing_spacing_in, used by\ncanon.py / corridas.py): all walls of a set with CRC @ 8\'-0" O.C. failed. Now the printed spacing is used, 48" by default.\nSynthetic. Fails with v81cf18 (no bracing_spacing)."""\nimport os, sys\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nimport reglas\nassert reglas.bracing_spacing({"constants": {"bracing_spacing_in": {"value": 96, "source": "X4.1 note 7"}}}) == 96.0\nassert reglas.bracing_spacing({"constants": {}}) == 48.0\nassert reglas.bracing_spacing(None) == 48.0\nprint("test_bracing_spacing_regla OK")\n'))
BLOQUES.append(('test_header_misc_regla', '#!/usr/bin/env python3\n"""test_header_misc_regla.py — BE-HF6 (HFT Loveland): reglas.py A_HEADER_LF (E1) compared the header / box beam family\nwith the openings of headers_in.json only; box beams / box headers drawn in a detail and carried as misc_items (added\nto the family by canon.py) made it fail. Synthetic. Fails with v81cf18 (no header_misc_lf)."""\nimport os, sys\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nimport reglas\nc = {"misc_items": [{"ref": "BB-1", "familia": "header / box beam", "qty": 100.5},\n                    {"ref": "X", "familia": "control joint", "qty": 7.0}]}\nassert abs(reglas.header_misc_lf(c) - 100.5) < 1e-9\nassert reglas.header_misc_lf({}) == 0\nprint("test_header_misc_regla OK")\nsrc = open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "trazabilidad.py"), encoding="utf-8").read()\nassert \'its += items_filas("header / box beam")\' in src, "trazabilidad header breakdown without the misc box beams"\nprint("test_header_misc_regla trazabilidad OK")\n'))
BLOQUES.append(('test_track_size_designacion', '#!/usr/bin/env python3\n"""test_track_size_designacion.py — BE-HF7 (HFT Loveland): trazabilidad.py compared walls[].stud_size with the size of\nthe track row by exact string, so a wall whose stud_size carries its designation (\'6" (600S162-54)\') was left out of\nthe per-size bottom / top track breakdown while canon.py had counted it -> ValueError \'desglose suma != NET\'.\nSynthetic. Fails with v81cf18 (no tamano_stud)."""\nimport os, sys\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nimport trazabilidad as Z\nassert Z.tamano_stud(\'6" (600S162-54)\') == \'6"\'\nassert Z.tamano_stud(\'3-5/8"\') == \'3-5/8"\'\nassert Z.tamano_stud(\'2-1/2"\') == \'2-1/2"\'\nassert Z.tamano_stud(None) is None\nsrc = open(Z.__file__, encoding="utf-8").read()\nassert \'tamano_stud(walls.get(r["id"][2:], {}).get("stud_size")) == sz\' in src\nprint("test_track_size_designacion OK")\n'))
BLOQUES.append(('test_cita_hoja_suelta', '#!/usr/bin/env python3\n"""test_cita_hoja_suelta.py — BE-HF8 (HFT Loveland): a Material Summary row whose items cite only a bare sheet ("X4.1 Wall\nType Note 5", a window of X1.1) and no N/SHEET bubble got "N/SHEET: default (no sheet)" and plantilla_excel verificar\nrejected the Excel. trazabilidad.aplicar now falls back to the bare sheets of the item / family-row sources.\nChecks the code path and the sheet regex (synthetic). Fails with v81cf18."""\nimport os, sys\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nimport trazabilidad as Z\nassert Z.RX_HOJA.findall("X4.1 Wall Type Note 5 \'ALL RETURNS\'") == ["X4.1"]\nsrc = open(Z.__file__, encoding="utf-8").read()\nassert "BE-HF8" in src and "RX_HOJA.findall(\\" \\".join(srcs))" in src and "with_sill_source" in src\nprint("test_cita_hoja_suelta OK")\n'))
BLOQUES.append(('test_markup_sin_board', '#!/usr/bin/env python3\n"""test_markup_sin_board.py — BE-HF9 (HFT Loveland): a wall declared without gypsum board (faces [] +\nfaces_none_reason, structural CFS wall sheathed by others) got "LF x H SF" in its Bluebeam markup while its Excel row\nsays 0 SF board -> verificar_markups_excel FAIL. board_sf() now returns 0 for it; a wall with no faces and no reason\nkeeps the old behaviour (None). Synthetic. Fails with v81cf18."""\nimport os, sys\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nimport markups_bluebeam as MB\nassert MB.board_sf({"id": "X-1", "faces": [], "faces_none_reason": "plywood sheathing by others"}) == 0.0\nassert MB.board_sf({"id": "X-2", "faces": []}) is None\nprint("test_markup_sin_board OK")\n'))
BLOQUES.append(('test_auditoria_rfis_causa', '#!/usr/bin/env python3\n"""test_auditoria_rfis_causa.py — BE-HF10 (HFT Loveland): auditoria_entrega.py (Chuze FINAL5) failed (a) every delivery\nwith open RFIs ("Pending Items empty") although the brief asks for the RFIs with options and the conservative value\nloaded, and (b) a drawn-length difference whose cause is written on the canon element (verificar_markups_excel accepts\nit). Now --rfis-abiertos checks each open RFI for (A)/(B)/(C) + delta, and check 3 accepts length_cause / area_cause /\nmeasure_cause / markup_cause. Synthetic. Fails with v81cf18."""\nimport os, sys\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nimport auditoria_entrega as A\nc = {"walls": [{"id": "X-2", "length_cause": "printed dimension governs"}], "misc_items": [{"ref": "DEMO-06", "length_cause": "printed"}]}\nassert A.causa_canon(c, "TO-X-2") == "printed dimension governs"\nassert A.causa_canon(c, "DEMO-DEMO-06") == "printed"\nassert A.causa_canon(c, "TO-X-9") is None\nassert A.rfi_ok(("RFI-01", "q", "(A) a - delta 0 | (B) b - delta 1 | (C) Other: ____"))\nassert not A.rfi_ok(("RFI-02", "q", "(A) only"))\nprint("test_auditoria_rfis_causa OK")\n'))
BLOQUES.append(('test_braces_rows_rev2', '#!/usr/bin/env python3\n"""test_braces_rows_rev2.py — HFT Loveland back-check rev1 (synthetic data, fails with v81cf18):\n BE-HF12 canon.braces_to_structure: printed wall bracing to structure (spacing + spacing bar) carried by program;\n BE-HF13 canon.bracing_min_altura: C.R. bracing only on walls higher than the printed minimum height;\n BE-HF14 partition_types: constants.partition_row_rule \'wall_id\' = one row per wall id; element with partition_row\n         + tag = typed row (inside the type blocks / grand total), markups subject = its tag;\n BE-HF11 canon.track_by_element: a head element that is a Partition Takeoff row goes by size / kind (slip row);\n BE-HF17 legend page in schedule order; BE-HF15 markups_demo: \'2 faces x 1 layer\' from layers_info; BE-HF16 trazabilidad: sill track breakdown, rounding note."""\nimport os, sys\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nimport canon, partition_types as PT, trazabilidad as Z, familias\nAQ = os.path.dirname(os.path.abspath(__file__))\nfa = lambda h: {"room": "R", "board": "5/8 regular", "layers": 1, "height_ft": h, "height_source": "X4.1"}\nd = {"constants": {}, "braces_to_structure": {"spacing_in": {"value": 48, "source": "X1.1 note 1"},\n                                              "structure_ft": {"value": 16.0, "source": "X1.2 chart"}},\n     "walls": [{"id": "<a>", "element": "wall", "length_ft": 10.0, "height_ft": 17.0, "faces": [fa(8.5), fa(17.0)]},\n               {"id": "<b>", "element": "wall", "length_ft": 10.0, "height_ft": 17.0, "faces": [fa(17.0), fa(17.0)]},\n               {"id": "<c>", "element": "wall", "length_ft": 6.0, "height_ft": 8.5, "faces": [fa(8.5)]}]}\nr = canon.braces_to_structure(d)\nassert [x["wall"] for x in r] == ["<a>"], r\nassert r[0]["pcs"] == 4 and abs(r[0]["len_ft"] - 7.5) < 1e-9 and abs(r[0]["brace_lf"] - 30.0) < 1e-9 and r[0]["bar_lf"] == 10.0\nassert abs(canon.braces_to_structure(d, length_factor=0.5)[0]["brace_lf"] - 15.0) < 1e-9\nassert canon.F_BRACE_ST in canon.FAMS and canon.F_BAR_ST in canon.FAMS\ndm = {"constants": {"bracing_min_height_ft": {"value": 12, "source": "X4.1 note 7"}}}\nassert canon.bracing_min_altura({"id": "<c>", "height_ft": 8.5}, "X", dm)["bracing_rows"] == 0\nassert "bracing_rows" not in canon.bracing_min_altura({"id": "<a>", "height_ft": 17.0}, "X", dm)\nassert "bracing_rows" not in canon.bracing_min_altura({"id": "<c>", "height_ft": 8.5}, "X", {"constants": {}})\nassert PT.tipo({"element": "vestibule_head", "tag": "VH", "partition_row": "yes"}, {}) == "BULKHEAD-VH"\nassert PT.tipo({"element": "vestibule_head", "tag": "VH", "partition_row": "BULKHEAD-VB"}, {}) == "BULKHEAD-VB"\nassert PT.tipo({"element": "vestibule_head", "tag": "VH"}, {}) is None\nf, j = PT._agrupar("T", [{"id": "<a>", "length_ft": 3.0}, {"id": "<b>", "length_ft": 2.0}], 18.0, "wall_id", 1, 0.25, 0.5, [])\nassert [x["ids"] for x in f] == [["<a>"], ["<b>"]]\nassert familias.familia("Metal stud brace to structure 6\\" x 20 GA", "lf") == canon.F_BRACE_ST\nassert "(NET 10.67: difference = rounding" in Z._desglose([("w1", 5.33), ("w2", 5.33)], 10.67, "LF", "x")\nfor f_, k in (("canon.py", "elif el in TRACK_HEADS and not (en_pt is not None and wid in en_pt)"),\n              ("markups_demo.py", "layers_info"), ("trazabilidad.py", \'fam == "sill track" and unit == "LF"\'),\n              ("partition_types.py", \'"wall_id"\'), ("markups_bluebeam.py", "partition_row"),\n              ("markups_bluebeam.py", "tot = {t: tot[t] for t in orden_types(canon, list(tot))}")):\n    assert k in open(os.path.join(AQ, f_), encoding="utf-8").read(), f_\nprint("test_braces_rows_rev2 OK")\n'))

def main():
    malos = []
    for n, src in BLOQUES:
        g = {"__name__": "__main__", "__file__": os.path.join(AQ, n + ".py")}
        try:
            exec(compile(src, n + ".py", "exec"), g)
        except Exception as e:  # noqa
            import traceback; traceback.print_exc()
            malos.append(n)
    print(f"test_hft_loveland: {len(BLOQUES) - len(malos)}/{len(BLOQUES)} bloques OK" + (" FALLAN " + ", ".join(malos) if malos else ""))
    return 1 if malos else 0


if __name__ == "__main__":
    sys.exit(main())
